const ZERO_WIDTH_RANGES = [
  [0x0300, 0x036f],
  [0x1ab0, 0x1aff],
  [0x20d0, 0x20f0],
  [0xfe20, 0xfe2f],
]

const WIDE_RANGES = [
  [0x1100, 0x115f],
  [0x2e80, 0xa4cf],
  [0xac00, 0xd7a3],
  [0xf900, 0xfaff],
  [0xfe30, 0xfe4f],
  [0xff00, 0xff60],
  [0xffe0, 0xffe6],
]

const SOFT_HYPHEN = 0x00ad

function inRanges(cp, ranges) {
  for (const [lo, hi] of ranges) {
    if (cp >= lo && cp <= hi) return true
  }
  return false
}

export function charWidth(cp) {
  if (cp === SOFT_HYPHEN) return 0
  if (inRanges(cp, ZERO_WIDTH_RANGES)) return 0
  if (inRanges(cp, WIDE_RANGES)) return 2
  return 1
}

export function widthOf(str) {
  let total = 0
  for (const ch of str) {
    total += charWidth(ch.codePointAt(0))
  }
  return total
}

export function stripSoftHyphens(str) {
  return str.replace(/­/g, '')
}
"}

