const SOFT_HYPHEN = '­'

// Split raw input text into paragraphs, each an array of words (words may
// still contain soft hyphens).
export function parseParagraphs(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const paragraphs = []
  let current = []

  for (const line of lines) {
    if (/^[ \t]*$/.test(line)) {
      if (current.length > 0) {
        paragraphs.push(current)
        current = []
      }
      continue
    }
    const words = line.split(/[ \t]+/).filter((w) => w.length > 0)
    current.push(...words)
  }
  if (current.length > 0) {
    paragraphs.push(current)
  }

  return paragraphs
}

// Lay out a single paragraph's words into lines that fit within `width`
// columns, breaking at soft hyphens as needed. Returns an array of lines,
// each an array of final display words (no unused soft hyphens).
export function layoutParagraph(words, width) {
  const queue = words.slice()
  const lines = []
  let currentLine = []
  let currentWidth = 0

  while (queue.length > 0) {
    const word = queue.shift()
    const wordWidth = widthOf(word)
    const sep = currentLine.length > 0 ? 1 : 0

    if (currentWidth + sep + wordWidth <= width) {
      currentLine.push(stripSoftHyphens(word))
      currentWidth += sep + wordWidth
      continue
    }

    const availableWidth = width - currentWidth - sep
    const hyphenPositions = []
    for (let i = 0; i < word.length; i++) {
      if (word[i] === SOFT_HYPHEN) hyphenPositions.push(i)
    }

    let chosen = -1
    for (let i = hyphenPositions.length - 1; i >= 0; i--) {
      const p = hyphenPositions[i]
      const prefix = stripSoftHyphens(word.slice(0, p))
      const prefixWidth = widthOf(prefix) + 1
      if (prefixWidth <= availableWidth) {
        chosen = p
        break
      }
    }

    if (chosen !== -1) {
      const prefix = stripSoftHyphens(word.slice(0, chosen)) + '-'
      currentLine.push(prefix)
      lines.push(currentLine)
      currentLine = []
      currentWidth = 0
      queue.unshift(word.slice(chosen + 1))
      continue
    }

    if (currentLine.length > 0) {
      lines.push(currentLine)
      currentLine = []
      currentWidth = 0
      queue.unshift(word)
      continue
    }

    currentLine.push(stripSoftHyphens(word))
    lines.push(currentLine)
    currentLine = []
    currentWidth = 0
  }

  if (currentLine.length > 0) {
    lines.push(currentLine)
  }

  return lines
}

function formatLine(words, width, justify) {
  if (!justify || words.length <= 1) {
    return words.join(' ')
  }

  const gaps = words.length - 1
  const wordsWidth = words.reduce((sum, w) => sum + widthOf(w), 0)
  const natural = wordsWidth + gaps
  if (natural >= width) {
    return words.join(' ')
  }

  const extra = width - wordsWidth
  const base = Math.floor(extra / gaps)
  const rem = extra % gaps

  let out = words[0]
  for (let i = 1; i < words.length; i++) {
    const gapIndex = i - 1
    const spaces = base + (gapIndex < rem ? 1 : 0)
    out += ' '.repeat(spaces) + words[i]
  }
  return out
}

export function render(text, mode, width) {
  const paragraphs = parseParagraphs(text)
  if (paragraphs.length === 0) return ''

  const justify = mode === 'justify'

  const paragraphTexts = paragraphs.map((words) => {
    const lines = layoutParagraph(words, width)
    const lastIndex = lines.length - 1
    const lineTexts = lines.map((lineWords, i) => {
      const isLast = i === lastIndex
      return formatLine(lineWords, width, justify && !isLast)
    })
    return lineTexts.join('\n')
  })

  return paragraphTexts.join('\n\n') + '\n'
}
