/**
 * The command. `node src/cli.js wrap <width>` fills each line up to the width
 * and `node src/cli.js justify <width>` also pads the gaps, over the text read
 * from standard input.
 */

import { readFileSync } from 'node:fs'
import { render } from './layout.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const args = process.argv.slice(2)

if (args.length !== 2 || (args[0] !== 'wrap' && args[0] !== 'justify')) {
  fail('usage: cli.js wrap|justify <width>')
}

const [mode, widthArg] = args

if (!/^[1-9][0-9]*$/.test(widthArg)) {
  fail('width must be a positive integer')
}

const width = Number(widthArg)

const input = readFileSync(0, 'utf8')

const output = render(input, mode, width)

process.stdout.write(output)
process.exit(0)
"}

